    23→export class TimelineService {
    24→  public static sendMessage = async (
    25→    roomId: string,
    26→    message: string,
    27→    mentions?: Mentions,
    28→    htmlBody?: string,
    29→  ) => {
    30→    const room = MatrixCore.getRoom(roomId);
    31→    const timeline = await room.timeline();
    32→    if (!timeline) throw new Error("Timeline not found");
    33→    let messageContent = htmlBody
    34→      ? messageEventContentFromHtml(message, htmlBody)
    35→      : messageEventContentFromMarkdown(message);
    36→    if (mentions) messageContent = messageContent.withMentions(mentions);
    37→    await timeline.send(messageContent);
    38→  };
    39→
    40→  public static replyToMessage = async (
    41→    roomId: string,
    42→    message: string,
    43→    eventId: string,
    44→    mentions?: Mentions,
    45→    htmlBody?: string,
    46→  ) => {
    47→    const room = MatrixCore.getRoom(roomId);
    48→    const timeline = await room.timeline();
    49→    if (!timeline) throw new Error("Timeline not found");
    50→    let messageContent = htmlBody
    51→      ? messageEventContentFromHtml(message, htmlBody)
    52→      : messageEventContentFromMarkdown(message);
    53→    if (mentions) messageContent = messageContent.withMentions(mentions);
    54→    await timeline.sendReply(messageContent, eventId);
    55→  };
    56→
    57→  public static editMessage = async (
    58→    roomId: string,
    59→    event: EventTimelineItem,
    60→    message: string,
    61→    mentions?: Mentions,
    62→    htmlBody?: string,
    63→  ) => {
    64→    const room = MatrixCore.getRoom(roomId);
    65→    const timeline = await room.timeline();
    66→    if (!timeline) throw new Error("Timeline not found");
    67→
    68→    if (!event.eventOrTransactionId) {
    69→      throw new Error("Event is missing event or transaction id");
    70→    }
    71→
    72→    let messageContent = htmlBody
    73→      ? messageEventContentFromHtml(message, htmlBody)
    74→      : messageEventContentFromMarkdown(message);
    75→    if (mentions) messageContent = messageContent.withMentions(mentions);
    76→
    77→    const editedContent = EditedContent.RoomMessage.new({
    78→      content: messageContent,
    79→    });
    80→    await timeline.edit(event.eventOrTransactionId, editedContent);
    81→  };
