   104→  public static forwardMessage = async (
   105→    roomId: string,
   106→    event: EventTimelineItem,
   107→    messageType: ForwardMessageType,
   108→  ) => {
   109→    const client = MatrixCore.getClient();
   110→    const room = MatrixCore.getRoom(roomId);
   111→    const timeline = await room.timeline();
   112→    if (!timeline) throw new Error("Timeline not found");
   113→
   114→    if (messageType === "text") {
   115→      const textContent = this.getTextContent(event);
   116→      if (!textContent) throw new Error("Text content not found");
   117→      await timeline.send(messageEventContentFromMarkdown(textContent));
   118→      return;
   119→    }
   120→
   121→    if (messageType === "image") {
   122→      const imageContent = this.getImageContent(event);
   123→      if (!imageContent) throw new Error("Image content not found");
   124→
   125→      const mediaFile = await client.getMediaFile(
   126→        imageContent.source,
   127→        imageContent.filename,
   128→        imageContent.info?.mimetype || "image/jpeg",
   129→        true,
   130→        undefined,
   131→      );
   132→      const filePath = mediaFile.path();
   133→      const fileSource: UploadParameters = {
   134→        source: new UploadSource.File({ filename: filePath }),
   135→        caption: imageContent.caption || undefined,
   136→        formattedCaption: undefined,
   137→        mentions: undefined,
   138→        inReplyTo: undefined,
   139→      };
   140→      const imageHandle = timeline.sendImage(
   141→        fileSource,
   142→        new UploadSource.File({ filename: filePath }),
   143→        {
   144→          height: imageContent.info?.height || BigInt(0),
   145→          width: imageContent.info?.width || BigInt(0),
   146→          mimetype: imageContent.info?.mimetype || "image/jpeg",
   147→          size: imageContent.info?.size || BigInt(0),
   148→          thumbnailInfo: imageContent.info?.thumbnailInfo,
   149→          thumbnailSource: undefined,
   150→          blurhash: imageContent.info?.blurhash || "",
   151→          isAnimated: false,
   152→        },
   153→      );
   154→      await imageHandle.join();
   155→      return;
   156→    }
   157→
   158→    if (messageType === "video") {
   159→      const videoContent = this.getVideoContent(event);
   160→      if (!videoContent) throw new Error("Video content not found");
   161→
   162→      const mediaFile = await client.getMediaFile(
   163→        videoContent.source,
   164→        videoContent.filename,
   165→        videoContent.info?.mimetype || "video/mp4",
   166→        true,
   167→        undefined,
   168→      );
   169→      const filePath = mediaFile.path();
   170→      const fileSource: UploadParameters = {
   171→        source: new UploadSource.File({ filename: filePath }),
   172→        caption: videoContent.caption || undefined,
   173→        formattedCaption: undefined,
   174→        mentions: undefined,
   175→        inReplyTo: undefined,
   176→      };
   177→      const videoHandle = timeline.sendVideo(
   178→        fileSource,
   179→        new UploadSource.File({ filename: filePath }),
   180→        {
   181→          height: videoContent.info?.height || BigInt(0),
   182→          width: videoContent.info?.width || BigInt(0),
   183→          mimetype: videoContent.info?.mimetype || "video/mp4",
   184→          size: videoContent.info?.size || BigInt(0),
   185→          duration: videoContent.info?.duration || 0,
   186→          thumbnailInfo: videoContent.info?.thumbnailInfo,
   187→          thumbnailSource: undefined,
   188→          blurhash: videoContent.info?.blurhash || "",
   189→        },
   190→      );
   191→      await videoHandle.join();
   192→      return;
   193→    }
   194→
   195→    if (messageType === "audio") {
   196→      const audioContent = this.getAudioContent(event);
   197→      if (!audioContent) throw new Error("Audio content not found");
   198→
   199→      const mediaFile = await client.getMediaFile(
   200→        audioContent.source,
   201→        audioContent.filename,
   202→        audioContent.info?.mimetype || "audio/mpeg",
   203→        true,
   204→        undefined,
   205→      );
   206→      const filePath = mediaFile.path();
   207→      const fileSource: UploadParameters = {
   208→        source: new UploadSource.File({ filename: filePath }),
   209→        caption: undefined,
   210→        formattedCaption: undefined,
   211→        mentions: undefined,
   212→        inReplyTo: undefined,
   213→      };
   214→      const audioHandle = timeline.sendAudio(fileSource, {
   215→        mimetype: audioContent.info?.mimetype || "audio/mpeg",
   216→        size: audioContent.info?.size || BigInt(0),
   217→        duration: audioContent.info?.duration || 0,
   218→      });
   219→      await audioHandle.join();
   220→      return;
   221→    }
   222→
   223→    if (messageType === "file") {
   224→      const fileContent = this.getFileContent(event);
   225→      if (!fileContent) throw new Error("File content not found");
   226→
   227→      const mediaFile = await client.getMediaFile(
   228→        fileContent.source,
   229→        fileContent.filename,
   230→        fileContent.info?.mimetype || "application/octet-stream",
   231→        true,
   232→        undefined,
   233→      );
   234→      const filePath = mediaFile.path();
   235→      timeline.sendFile(
   236→        {
   237→          source: new UploadSource.File({ filename: filePath }),
   238→          caption: undefined,
   239→          formattedCaption: undefined,
   240→          mentions: undefined,
   241→          inReplyTo: undefined,
   242→        },
   243→        {
   244→          size: fileContent.info?.size || BigInt(0),
   245→          mimetype: fileContent.info?.mimetype || "application/octet-stream",
   246→          thumbnailInfo: undefined,
   247→          thumbnailSource: undefined,
   248→        },
   249→      );
   250→      return;
   251→    }
   252→
   253→    throw new Error(`Unsupported message type: ${messageType}`);
   254→  };
