   256→  public static sendAttachment = async (
   257→    roomId: string,
   258→    attachment: DocumentPickerResponse,
   259→  ) => {
   260→    const room = MatrixCore.getRoom(roomId);
   261→    const timeline = await room.timeline();
   262→    if (!timeline) throw new Error("Timeline not found");
   263→    timeline.sendFile(
   264→      {
   265→        source: new UploadSource.File({
   266→          filename: attachment.uri.replace("file://", ""),
   267→        }),
   268→        caption: undefined,
   269→        formattedCaption: undefined,
   270→        mentions: undefined,
   271→        inReplyTo: undefined,
   272→      },
   273→      {
   274→        size: BigInt(attachment.size || 0),
   275→        mimetype: attachment.type || "application/octet-stream",
   276→        thumbnailInfo: undefined,
