   282→  public static sendMedia = async (
   283→    roomId: string,
   284→    asset: Asset,
   285→    caption?: string,
   286→  ) => {
   287→    if (!asset?.uri) throw new Error("No uri found");
   288→    const room = MatrixCore.getRoom(roomId);
   289→    const timeline = await room.timeline();
   290→    if (!timeline) throw new Error("Timeline not found");
   291→
   292→    const type = asset.type ?? "image/jpeg";
   293→    const assetWidth = asset.width ?? 0;
   294→    const assetHeight = asset.height ?? 0;
   295→    const isVideo = type.startsWith("video/");
   296→
   297→    const fileSource: UploadParameters = {
   298→      source: new UploadSource.File({
   299→        filename: asset.uri.replace("file://", ""),
   300→      }),
   301→      caption: caption || undefined,
   302→      formattedCaption: undefined,
   303→      mentions: undefined,
   304→      inReplyTo: undefined,
   305→    };
   306→
   307→    if (isVideo) {
   308→      const videoHandle = timeline.sendVideo(
   309→        fileSource,
   310→        new UploadSource.File({ filename: asset.uri.replace("file://", "") }),
   311→        {
   312→          height: BigInt(assetHeight),
   313→          width: BigInt(assetWidth),
   314→          mimetype: type,
   315→          size: BigInt(asset.fileSize ?? 0),
   316→          duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
   317→          thumbnailInfo: {
   318→            height: BigInt(assetHeight),
   319→            width: BigInt(assetWidth),
   320→            mimetype: type,
   321→            size: BigInt(asset.fileSize ?? 0),
   322→          },
   323→          thumbnailSource: undefined,
   324→          blurhash: "",
   325→        },
   326→      );
   327→      await videoHandle.join();
   328→    } else {
   329→      const imageHandle = timeline.sendImage(
   330→        fileSource,
   331→        new UploadSource.File({ filename: asset.uri.replace("file://", "") }),
   332→        {
   333→          height: BigInt(assetHeight),
   334→          width: BigInt(assetWidth),
   335→          mimetype: type,
   336→          size: BigInt(asset.fileSize ?? 0),
   337→          thumbnailInfo: {
   338→            height: BigInt(assetHeight),
   339→            width: BigInt(assetWidth),
   340→            mimetype: type,
   341→            size: BigInt(asset.fileSize ?? 0),
   342→          },
   343→          thumbnailSource: undefined,
   344→          blurhash: "",
   345→          isAnimated: false,
   346→        },
   347→      );
   348→      await imageHandle.join();
   349→    }
   350→  };
