   361→  public static getSeenBy = (event: EventTimelineItem) => event.readReceipts;
   362→
   363→  public static getReadReceipts = async (event: EventTimelineItem) => {
   364→    const userIds = Array.from(event.readReceipts.keys());
   365→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
   366→
   367→    if (!filteredUserIds.length) return [];
   368→
   369→    try {
   370→      const client = MatrixCore.getClient();
   371→      const profilePromises = filteredUserIds.map((userId) =>
   372→        client.getProfile(userId),
   373→      );
   374→      const profiles = await Promise.allSettled(profilePromises);
   375→      return profiles
   376→        .filter((p) => p.status === "fulfilled")
   377→        .map((p) => p.value)
   378→        .filter((p) => p !== undefined);
   379→    } catch (error) {
   380→      console.error("Failed to get read receipt users:", error);
   381→      return [];
   382→    }
   383→  };
