   417→  public static isMessagePinned = async (
   418→    roomId: string,
   419→    eventId: string,
   420→  ): Promise<boolean> => {
   421→    const pinnedEvents = await this.getPinnedEventIds(roomId);
   422→    return pinnedEvents.includes(eventId);
