   427→  private static getTextContent = (event: EventTimelineItem): string | null => {
   428→    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
   429→      const kind = event.content.inner.content.kind;
   430→      if (kind?.tag === MsgLikeKind_Tags.Message) {
   431→        return kind.inner.content.body;
   432→      }
   433→    }
   434→    return null;
   435→  };
   436→
   437→  private static getImageContent = (
   438→    event: EventTimelineItem,
   439→  ): ImageMessageContent | null => {
   440→    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
   441→      const kind = event.content.inner.content.kind;
   442→      if (kind?.tag === MsgLikeKind_Tags.Message) {
   443→        const msgType = kind.inner.content.msgType;
   444→        if (msgType?.tag === MessageType_Tags.Image) {
   445→          return msgType.inner.content;
   446→        }
   447→      }
   448→    }
   449→    return null;
   450→  };
   451→
   452→  private static getVideoContent = (
   453→    event: EventTimelineItem,
   454→  ): VideoMessageContent | null => {
   455→    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
   456→      const kind = event.content.inner.content.kind;
   457→      if (kind?.tag === MsgLikeKind_Tags.Message) {
   458→        const msgType = kind.inner.content.msgType;
   459→        if (msgType?.tag === MessageType_Tags.Video) {
   460→          return msgType.inner.content;
