   466→
   467→  private static getAudioContent = (
   468→    event: EventTimelineItem,
   469→  ): AudioMessageContent | null => {
   470→    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
   471→      const kind = event.content.inner.content.kind;
   472→      if (kind?.tag === MsgLikeKind_Tags.Message) {
   473→        const msgType = kind.inner.content.msgType;
   474→        if (msgType?.tag === MessageType_Tags.Audio) {
   475→          return msgType.inner.content;
   476→        }
   477→      }
   478→    }
   479→    return null;
   480→  };
   481→
   482→  private static getFileContent = (
   483→    event: EventTimelineItem,
   484→  ): FileMessageContent | null => {
   485→    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
   486→      const kind = event.content.inner.content.kind;
   487→      if (kind?.tag === MsgLikeKind_Tags.Message) {
   488→        const msgType = kind.inner.content.msgType;
   489→        if (msgType?.tag === MessageType_Tags.File) {
   490→          return msgType.inner.content;
   491→        }
   492→      }
   493→    }
   494→    return null;
   495→  };
