    81→  public static createRoom = async (
    82→    roomName: string,
    83→    type: "private" | "public",
    84→    image: Asset | null,
    85→    roomTopic?: string,
    86→  ): Promise<string> => {
    87→    const client = MatrixCore.getClient();
    88→
    89→    try {
    90→      const roomOptions: CreateRoomParameters = {
    91→        name: roomName,
    92→        topic: roomTopic,
    93→        preset:
    94→          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
    95→        avatar: undefined,
    96→        isEncrypted: type === "private",
    97→        isDirect: false,
    98→        visibility:
    99→          type === "private"
   100→            ? new RoomVisibility.Private()
   101→            : new RoomVisibility.Public(),
   102→        invite: [],
   103→        powerLevelContentOverride: undefined,
   104→        joinRuleOverride: undefined,
   105→        historyVisibilityOverride: undefined,
   106→        canonicalAlias: undefined,
   107→      };
   108→
   109→      const roomId = await client.createRoom(roomOptions);
   110→
   111→      if (image?.base64) {
   112→        const room = client.getRoom(roomId);
   113→        const bytes = Buffer.from(image.base64, "base64");
   114→        const mimeType = image.type ?? "image/jpeg";
   115→
   116→        if (!room) throw new Error("Room not found");
   117→        await room.uploadAvatar(mimeType, bytes.buffer, {
   118→          height: BigInt(32),
   119→          width: BigInt(32),
   120→          mimetype: mimeType,
   121→          size: BigInt(image.fileSize ?? 0),
   122→          thumbnailInfo: {
   123→            height: BigInt(32),
   124→            width: BigInt(32),
   125→            mimetype: mimeType,
   126→            size: BigInt(image.fileSize ?? 0),
   127→          },
   128→          thumbnailSource: undefined,
   129→          blurhash: "",
   130→          isAnimated: false,
   131→        });
