     4→/** Filter out duplicate stateKeys for calls */
     5→export const filterSameStateKey = (events: EventTimelineItem[]) => {
     6→  const seenStateKeys = new Map<string, EventTimelineItem>();
     7→  const filtered: EventTimelineItem[] = [];
     8→
     9→  for (const event of events) {
    10→    const stateKey =
    11→      event.content.tag === TimelineItemContent_Tags.State &&
    12→      event.content.inner.stateKey
    13→        ? event.content.inner.stateKey
    14→        : null;
    15→
    16→    if (stateKey) {
    17→      if (!seenStateKeys.has(stateKey)) {
    18→        seenStateKeys.set(stateKey, event);
    19→      }
    20→    } else filtered.push(event);
    21→  }
    22→
    23→  const stateKeyEvents = Array.from(seenStateKeys.values());
    24→  return [...filtered, ...stateKeyEvents].sort(
    25→    (a, b) => Number(a.timestamp) - Number(b.timestamp),
    26→  );
    27→};
    28→
    29→export const handleIsPreviousSameSender = (
    30→  isDirect: boolean,
    31→  events: EventTimelineItem[],
    32→  currentEvent: EventTimelineItem,
    33→  index: number,
    34→) => {
    35→  if (isDirect) return true;
    36→  const messageTypesEvents = events.filter((event) => {
    37→    return event.content.tag === TimelineItemContent_Tags.MsgLike;
    38→  });
    39→
    40→  return messageTypesEvents[index - 1]?.sender === currentEvent?.sender;
    41→};
