     3→const formatTimelineDate = (timestamp: bigint): string => {
     4→  const date = new Date(Number(timestamp));
     5→  const today = new Date();
     6→  const yesterday = new Date(today);
     7→  yesterday.setDate(yesterday.getDate() - 1);
     8→
     9→  const dateOnly = new Date(
    10→    date.getFullYear(),
    11→    date.getMonth(),
    12→    date.getDate(),
    13→  );
    14→  const todayOnly = new Date(
    15→    today.getFullYear(),
    16→    today.getMonth(),
    17→    today.getDate(),
    18→  );
    19→  const yesterdayOnly = new Date(
    20→    yesterday.getFullYear(),
    21→    yesterday.getMonth(),
    22→    yesterday.getDate(),
    23→  );
    24→
    25→  if (dateOnly.getTime() === todayOnly.getTime()) return "Today";
    26→
    27→  if (dateOnly.getTime() === yesterdayOnly.getTime()) return "Yesterday";
    28→
    29→  return date.toLocaleDateString("en-US", {
    30→    weekday: "long",
    31→    year: "numeric",
    32→    month: "long",
    33→    day: "numeric",
    34→  });
    35→};
    36→
    37→/** Helper function to group events by date and add dividers */
    38→export const addDateDividers = (
    39→  events: EventTimelineItem[],
    40→): TimelineListItem[] => {
    41→  const result: TimelineListItem[] = [];
    42→  let lastDate: string | null = null;
    43→
    44→  for (const event of events) {
    45→    const eventDate = formatTimelineDate(event.timestamp);
    46→
    47→    if (eventDate !== lastDate) {
    48→      result.push({
    49→        type: "divider",
    50→        date: eventDate,
    51→        id: `divider-${event.timestamp}`,
    52→      });
    53→      lastDate = eventDate;
    54→    }
    55→
    56→    result.push({ type: "event", data: event });
    57→  }
    58→
    59→  return result;
    60→};
